<div class="admin-page-heading"><div><h1><?= $this->h($user['display_name']?:'اطلاعات کاربر') ?></h1><p class="small muted">شناسه ثابت: <bdi><?= $this->h($user['id']) ?></bdi></p></div><a class="secondary" href="<?= $this->h($this->url('/users')) ?>">بازگشت به کاربران</a></div>
<div class="admin-user-columns section"><section class="card"><h2>اطلاعات حساب</h2><p>شماره همراه: <bdi><?= $this->h($user['phone']??'ثبت نشده') ?></bdi> <?= $user['phone_verified_at']?'· تأییدشده':'' ?></p><p class="small muted">شمارهٔ تأییدشده از این بخش تغییر نمی‌کند؛ تغییر آن نیازمند اثبات مالکیت است.</p>
<?php if(empty($profile['deleted_at'])): ?><?= $this->start('/users/update') ?><input type="hidden" name="id" value="<?= $this->h($user['id']) ?>"><?php require __DIR__.'/profile-fields.php'; ?><?= $this->field('username','نام کاربری','text',$username,true,32) ?><?= $this->field('current_password','رمز فعلی مدیر برای تأیید ویرایش','password') ?><button class="primary">ذخیره اطلاعات کاربر</button></form><?php else: ?><p class="notice">این حساب حذف شده است. برای ویرایش ابتدا آن را بازیابی کنید.</p><?php endif; ?></section>
<div class="records"><section class="card"><h2>صاحب تجربه / مرشد</h2><?php if($mentor): ?><p>وضعیت: <?= $this->status($mentor['status']) ?></p><p>پذیرش دعوت: <?= $mentor['accepted_at']?'انجام شده':'در انتظار کاربر' ?></p><a class="secondary" href="<?= $this->h($this->url('/mentors?q='.$user['display_name'])) ?>">مدیریت پرونده مرشد</a><?php elseif($user['status']==='active'&&empty($profile['deleted_at'])): ?><p>این کاربر هنوز پروندهٔ مرشد ندارد.</p><a class="primary" href="<?= $this->h($this->url('/mentors?user_id='.$user['id'])) ?>">دعوت این کاربر به مرشدشدن</a><?php endif; ?></section>
<?php if($user['id']!==$this->actor['user_id']): ?><details class="card admin-user-actions"><summary>مدیریت وضعیت و دسترسی حساب</summary><?php if(empty($profile['deleted_at'])): ?><?= $this->start('/users/status') ?><input type="hidden" name="id" value="<?= $this->h($user['id']) ?>"><input type="hidden" name="status" value="<?= $user['status']==='active'?'blocked':'active' ?>"><?= $this->field('current_password','رمز فعلی مدیر','password') ?><button class="secondary"><?= $user['status']==='active'?'محدودکردن حساب و بستن نشست‌ها':'فعال‌کردن حساب' ?></button></form><?php endif; ?><?= $this->start(!empty($profile['deleted_at'])?'/users/restore':'/users/delete') ?><input type="hidden" name="id" value="<?= $this->h($user['id']) ?>"><?= $this->field('current_password','رمز فعلی مدیر','password') ?><button class="secondary"><?= !empty($profile['deleted_at'])?'بازیابی کاربر':'حذف قابل‌بازیابی و بستن دسترسی' ?></button></form></details><?php endif; ?></div></div>
